set tempo 80
set key G
set mode minor

chords phrase = 1m7 4m7 | 6maj7 5dom7

play (
  block { with octave 4 { piano: chords phrase } }
  block { with octave 4 { organ: chords fifth(phrase) } }
)

set tempo 90
set octave 4

chords two = 2m7
chords cadence = two|fourth(two)|second(two, -1) -

play (
  with key C { piano: chords cadence }
  with key F { piano: chords cadence }
  with key Bb { piano: chords cadence }
)
